/** @jsxRuntime automatic */
/** @jsxImportSource $tsx-preact */

import { type VNode } from "$tsx-preact";
import { useSignal, useSignalEffect } from "$tsx-preact-signal";
import { useContext } from "$tsx-preact/hooks";
import { LngLat } from "$map-libre-gl";
import { MapContext } from "../core/MapCanvas.tsx";
import { mapOptions_instanceVarInitCamera as cameraStateReset, type MapOptions_InstanceVarInitCamera as CameraState } from "../store/MapOptions_store.ts";
import { isCameraFrameVisible, isMapInteractive } from "../store/MapState_signals.ts"; // <-- DODANO IMPORT
import { PanelOverCanvas, SectionOverCanvas, ButtonOverCanvas } from "./PanelOverCanvas.tsx";

/**
 * Panel do sterowania i odczytywania stanu kamery mapy.
 */
export function CameraFrame(): VNode | null {
    // Jeśli sygnał globalny nakazuje ukrycie panelu, nic nie renderujemy.
    if (!isCameraFrameVisible.value) {
        return null;
    }

    // używamy useContext do pobrania instancji mapy z dostawcy,
    // ale cały stan komponentu jest zarządzany przez sygnały.
    const mapCanvas = useContext(MapContext);

    // --- Sygnały ---
    // Sygnał dla stanu kamery, zsynchronizowany z mapą.
    const cameraState = useSignal<CameraState | null>(null);
    // Sygnał dla wartości "roll", zarządzany osobno.
    const roll = useSignal<number>(0);
    // Sygnał dla widoczności panelu.
    const isExpanded = useSignal(false);


    // --- Efekt Sygnału ---
    // Ten efekt uruchamia się, gdy obiekt 'map' jest dostępny. Ustawia stan początkowy
    // i subskrybuje zdarzenia mapy. Sprząta po sobie, gdy komponent jest odmontowywany.
    useSignalEffect(() => {
        if (!mapCanvas) return;
        //mapCanvas.addControl(new )

        // Funkcja do aktualizacji sygnału stanu komponentu na podstawie instancji mapy.
        const updateStateFromMap = () => {
            const center = mapCanvas.getCenter();
            // Przypisanie nowego obiektu do .value wyzwala aktualizację sygnału.
            cameraState.value = {
                zoom: mapCanvas.getZoom(),
                center: new LngLat(center.lng, center.lat),
                bearing: mapCanvas.getBearing(),
                pitch: mapCanvas.getPitch()
            };
            isMapInteractive.value = mapCanvas.dragPan.isEnabled() && mapCanvas.scrollZoom.isEnabled();
        };

        updateStateFromMap(); // Inicjalizuj stan natychmiast.
        mapCanvas.on('move', updateStateFromMap); // Nasłuchuj na zdarzenie 'move', aby na bieżąco aktualizować pola wejściowe.

        // Funkcja czyszcząca na czas odmontowania komponentu.
        return () => {
            mapCanvas.off('move', updateStateFromMap);
        };
    });


    // --- Handlery ---

    // Handler do zmiany wartości w polach wejściowych. Aktualizuje sygnał cameraState.
    const handleInputChange = (field: keyof Omit<CameraState, 'center'>, value: number | boolean) => {
        if (!cameraState.value) return;
        // Utwórz nowy obiekt stanu i przypisz go do .value sygnału, aby wywołać aktualizacje.
        cameraState.value = { ...cameraState.value, [field]: value };
    };
    
    const handleCenterChange = (coord: 'lng' | 'lat', value: number) => {
        if (!cameraState.value) return;
        const currentCenter = cameraState.value.center;
        const newLng = coord === 'lng' ? value : currentCenter.lng;
        const newLat = coord === 'lat' ? value : currentCenter.lat;

        cameraState.value = {
            ...cameraState.value,
            center: new LngLat(newLng, newLat)
        };
    };

    // Handler dla przycisku "Idź do". Odczytuje bieżące wartości sygnału.
    const handleGoTo = () => {
        if (!mapCanvas || !cameraState.value) return;

        mapCanvas.flyTo({
            center: new LngLat(cameraState.value.center.lng, cameraState.value.center.lat),
            zoom: cameraState.value.zoom,
            pitch: cameraState.value.pitch,
            bearing: cameraState.value.bearing,
        });
    };

    // Handler dla przycisku "Resetuj".
    const handleGoToReset = () => {
        if (!mapCanvas) return;
        // Użyj zaimportowanego obiektu resetowania bezpośrednio do animacji, aby zapewnić spójność.
        mapCanvas.flyTo({
            center: new LngLat(cameraStateReset.center.lng, cameraStateReset.center.lat),
            zoom: cameraStateReset.zoom,
            pitch: cameraStateReset.pitch,
            bearing: cameraStateReset.bearing,
        });
        mapCanvas.setRoll(0);

        // Zaktualizuj sygnały, aby interfejs użytkownika natychmiast odzwierciedlał stan resetowania.
        // Nasłuchiwacz zdarzeń 'move' zsynchronizuje stan po zakończeniu animacji.
        cameraState.value = cameraStateReset;
        roll.value = 0;
    };

    // Handler dla pola "Obrót".
    const handleChangeRoll = (newRoll: number) => {
        if (!mapCanvas) return;
        roll.value = newRoll;
        // Nowa wartość jest natychmiast stosowana na mapie.
        mapCanvas.setRoll(roll.value);
    };

    
    // --- Funkcje Schowka ---
    // UWAGA: Używanie alert() i prompt() jest generalnie odradzane w nowoczesnych interfejsach użytkownika.
    // Rozważ zastąpienie ich niestandardowym komponentem modala/toastu dla lepszego doświadczenia użytkownika.

    const fallbackCopyTextToClipboard = (text: string) => {
        const textArea = document.createElement("textarea");
        textArea.value = text;
        document.body.appendChild(textArea);
        textArea.focus();
        textArea.select();
        try {
            // document.execCommand jest przestarzałe, ale służy jako metoda zastępcza.
            document.execCommand('copy');
        } catch (err) {
            console.error('Kopiowanie zastępcze nie powiodło się:', err);
        }
        document.body.removeChild(textArea);
    };

    const handleCopy = () => {
        if (!cameraState.value) return;
        const combinedState = { ...cameraState.value, roll: roll.value };
        const stateString = JSON.stringify(combinedState, null, 2);

        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(stateString).catch(() => {
                fallbackCopyTextToClipboard(stateString);
            });
        } else {
            fallbackCopyTextToClipboard(stateString);
        }
    };

    const handlePaste = () => {
        const text = prompt("Wklej skopiowany stan kamery (JSON):");
        if (!text) return;

        try {
            const parsed = JSON.parse(text);
            if ('zoom' in parsed && 'center' in parsed && 'roll' in parsed) {
                const { roll: parsedRoll, ...restOfState } = parsed;
                cameraState.value = restOfState;
                roll.value = parsedRoll;
            } else {
                alert('Nieprawidłowy format danych.');
            }
        } catch (err) {
            console.error('Błąd wklejania lub parsowania:', err);
            alert('Nie udało się wkleić lub sparsować stanu. Sprawdź konsolę.');
        }
    };

    // --- Renderowanie ---

    // Wyświetl komunikat o ładowaniu, dopóki mapa i stan kamery nie zostaną zainicjalizowane.
    if (!cameraState.value) {
        return (
            <div className="cameraState-frame loading">
                Ładowanie panelu kamery...
            </div>
        );
    }

    return (
        <PanelOverCanvas 
            position={{ zIndex: 10, top: 10, right: 50, width: 280 }} 
            flexFlow={`column nowrap`}
            title="Kamera"
            toggle={isExpanded}
            childrenHeader={(<div className="frame-header-toggle-interactive input-group checkbox-group">
                    <label htmlFor="interactive-checkbox">ruch</label>
                    {/* POPRAWIONY CHECKBOX - teraz korzysta z globalnego sygnału */}
                    <input 
                        id="interactive-checkbox" 
                        type="checkbox" 
                        checked={isMapInteractive.value} 
                        onChange={(e) => isMapInteractive.value = (e.target as HTMLInputElement).checked} 
                    />
                </div>)}
        >            
            {/* Zawartość jest renderowana warunkowo na podstawie sygnału isExpanded. */}
            {isExpanded.value && (
                <>
                    <SectionOverCanvas flexFlow={`column wrap`}>
                        <div className="input-group">
                            <label>Środek (Lng, Lat)</label>
                            <div className="split-input">
                                <input type="number" step="0.0001" value={cameraState.value.center.lng} onInput={(e) => handleCenterChange('lng', parseFloat((e.target as HTMLInputElement).value))} />
                                <input type="number" step="0.0001" value={cameraState.value.center.lat} onInput={(e) => handleCenterChange('lat', parseFloat((e.target as HTMLInputElement).value))} />
                            </div>
                        </div>
                        <div className="input-group">
                            <label>Zoom | Kierunek | Nachylenie</label>
                            <div className="split-input">
                                <input type="number" step="0.1" value={cameraState.value.zoom} onInput={(e) => handleInputChange('zoom', parseFloat((e.target as HTMLInputElement).value))} />
                                <input type="number" step="1" value={cameraState.value.bearing} onInput={(e) => handleInputChange('bearing', parseInt((e.target as HTMLInputElement).value, 10))} />
                                <input type="number" step="1" value={cameraState.value.pitch} onInput={(e) => handleInputChange('pitch', parseInt((e.target as HTMLInputElement).value, 10))} />
                            </div>                            
                        </div>
                    </SectionOverCanvas>
                    <SectionOverCanvas flexFlow={`row nowrap`}>
                        <ButtonOverCanvas title="copy"  onClickHandle={handleCopy}/>
                        <ButtonOverCanvas title="past"  onClickHandle={handlePaste}/>
                        <ButtonOverCanvas title="reset" onClickHandle={handleGoToReset} color="darkblue-button-over-canvas"/>
                        <ButtonOverCanvas title="go to" onClickHandle={handleGoTo} color="blue-button-over-canvas"/>
                    </SectionOverCanvas>
                    <SectionOverCanvas flexFlow={`column wrap`}>
                        <div className="input-group">
                            <label>Obrót</label>
                            <input type="number" step="1" value={roll.value} onInput={(e) => handleChangeRoll(parseInt((e.target as HTMLInputElement).value, 10))} />
                        </div>
                    </SectionOverCanvas>
                </>
            )}
        </PanelOverCanvas>
    );
}
