// --- Prywatna funkcja pomocnicza ---
const clamp = (num: number, min: number, max: number) => Math.max(min, Math.min(num, max));

// --- Funkcje Modyfikujące (API do zapisu stanu z walidacją) ---

export function setMapZoom(newZoom: number):void {
  const validated = clamp(newZoom, RANGE_ZOOM.noLessTHAN!, RANGE_ZOOM.noMoreTHAN!);
  const inverseStep = 1 / RANGE_ZOOM.stepSIZE!;
  mapOptions_instanceVar.zoom.value = Math.round(validated * inverseStep) / inverseStep;
}

export function setMapCenter(newCenter: { lng: number, lat: number } | LngLat | null) {
  if (!newCenter) {
    mapOptions_instanceVar.center.value = new LngLat(0, 0);
    return;
  }

  let lat = newCenter.lat;
  if (lat <= RANGE_CENTER_LAT.moreTHAN!) lat = RANGE_CENTER_LAT.moreTHAN! + 0.000001;
  if (lat >= RANGE_CENTER_LAT.noMoreTHAN!) lat = RANGE_CENTER_LAT.noMoreTHAN! - 0.000001;

  let lng = new LngLat(newCenter.lng, lat).wrap().lng;
  if (lng <= RANGE_CENTER_LNG.moreTHAN!) lng = RANGE_CENTER_LNG.noMoreTHAN!;

  mapOptions_instanceVar.center.value = new LngLat(lng, lat);
}

export function setMapBearing(newBearing: number) {
  let normalized = newBearing;
  while (normalized <= RANGE_BEARING.moreTHAN!) normalized += 360;
  while (normalized > RANGE_BEARING.noMoreTHAN!) normalized -= 360;

  const inverseStep = 1 / RANGE_BEARING.stepSIZE!;
  mapOptions_instanceVar.bearing.value = Math.round(normalized * inverseStep) / inverseStep;
}

export function setMapPitch(newPitch: number) {
  const validated = clamp(newPitch, RANGE_PITCH.noLessTHAN!, RANGE_PITCH.noMoreTHAN!);
  mapOptions_instanceVar.pitch.value = Math.round(validated);
}

export function updateCameraState(cameraState: { zoom: number; center: LngLat; bearing: number; pitch: number; }) {
    setMapZoom(cameraState.zoom);
    setMapCenter(cameraState.center);
    setMapBearing(cameraState.bearing);
    setMapPitch(cameraState.pitch);
}
