import { signal } from "$tsx-preact-signal";

/** Sygnał kontrolujący widoczność panelu CameraFrame. */
const isCameraFrameVisible = signal<boolean>(false);

/** Sygnał kontrolujący widoczność panelu MapControls. */
const isMapControlsVisible = signal<boolean>(false);

/** Sygnał kontrolujący, czy interakcje z mapą (przesuwanie, zoom) są włączone. */
const isMapInteractive = signal<boolean>(true);

/** Sygnał kontrolujący widoczność dużego panelu wyboru warstw bazowych. */
const isBaseLayersPanelVisible = signal<boolean>(false); // Domyślnie ukryty

export {
  isCameraFrameVisible,
  isMapControlsVisible,
  isMapInteractive,
  isBaseLayersPanelVisible
};
