/** @jsxRuntime automatic */
/** @jsxImportSource $tsx-preact */

import { type VNode } from "$tsx-preact";
import { useSignal, useSignalEffect, signal, effect } from "$tsx-preact-signal";
import { useContext, useRef } from "$tsx-preact/hooks";
import { MapContext } from "../core/MapCanvas.tsx";
import { 
    isBaseLayersPanelVisible,
    isCameraFrameVisible, 
    isMapControlsVisible, 
    isMapInteractive 
} from "../store/MapState_signals.ts";
import { 
    FullscreenControl,
    NavigationControl,
    ScaleControl,
    GeolocateControl,
    GlobeControl,
    TerrainControl,
    type Map,
    type ControlPosition,
    type IControl,
    type NavigationControlOptions,
    type FullscreenControlOptions,
    type ScaleControlOptions,
    type GeolocateControlOptions,
    type TerrainSpecification
} from "$map-libre-gl$"; 
import { PanelOverCanvas,SectionOverCanvas } from "./PanelOverCanvas.tsx";

// --- Niestandardowe Klasy Kontrolek implementujące IControl ---
class BaseLayersPanelControl implements IControl {
    _btn!: HTMLButtonElement;
    _container!: HTMLElement;
    _disposeEffect!: () => void;
    onAdd(map: Map) {
        this._container = document.createElement('div');
        this._container.className = 'maplibregl-ctrl maplibregl-ctrl-group';
        this._btn = document.createElement('button');
        this._btn.className = 'maplibregl-ctrl-icon';
        this._btn.type = 'button';
        this._btn.title = 'Zmień warstwę podkładową';
        this._btn.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="29" height="29" viewBox="-3 -3 30 30" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"></path></svg>`;
        this._btn.onclick = () => isBaseLayersPanelVisible.value = !isBaseLayersPanelVisible.value;
        this._disposeEffect = effect(() => {
            this._btn.classList.toggle('maplibregl-ctrl-icon-active', isBaseLayersPanelVisible.value);
        });
        this._container.appendChild(this._btn);
        return this._container;
    }
    onRemove() {
        this._disposeEffect();
        this._container.parentNode?.removeChild(this._container);
    }
}

