// --- Definicja Stanu i Opcji Kontrolek ---

type ControlState<T> = { enabled: boolean; position: ControlPosition; options: T; };

const controlsState = signal({
    // Standardowe kontrolki
    terrain: { enabled: true, position: 'top-right', options: { source: 'terrainSource', exaggeration: 2.2 } } as ControlState<TerrainSpecification>,
    globe: { enabled: true, position: 'top-right', options: {} } as ControlState<{}>,
    navigation: { enabled: true, position: 'top-right', options: { visualizePitch: true, visualizeRoll: true, showZoom: true, showCompass: true } } as ControlState<NavigationControlOptions>,
    fullscreen: { enabled: true, position: 'top-right', options: {} } as ControlState<FullscreenControlOptions>,
    scale: { enabled: true, position: 'bottom-left', options: { maxWidth: 100, unit: 'metric' } } as ControlState<ScaleControlOptions>,
    geolocate: { enabled: true, position: 'top-right', options: { positionOptions: { enableHighAccuracy: true }, trackUserLocation: true } } as ControlState<GeolocateControlOptions>,
    // Niestandardowe kontrolki UI
    baseLayers: { enabled: true, position: 'top-right', options: {} } as ControlState<{}>,
    cameraPanel: { enabled: true, position: 'top-right', options: {} } as ControlState<{}>,
    controlsPanel: { enabled: true, position: 'top-right', options: {} } as ControlState<{}>,
    interaction: { enabled: true, position: 'top-right', options: {} } as ControlState<{}>,
});

/**
 * Komponent-panel do dynamicznego zarządzania standardowymi kontrolkami MapLibre.
 */
export function MapControls(): VNode | null {
    const mapCanvas = useContext(MapContext);
    const activeControls = useRef<Record<string, IControl>>({});
    const styleRevision = useSignal(0);

    // Ten efekt jest teraz odpowiedzialny WYŁĄCZNIE za dodawanie/usuwanie kontrolek na mapie.
    // Działa niezależnie od tego, czy panel jest widoczny.
    useSignalEffect(() => {
        if (!mapCanvas) return;

        const onStyleData = () => styleRevision.value++;
        mapCanvas.on('styledata', onStyleData);

        const state = controlsState.value;
        const _ = styleRevision.value;

        const manageControl = (name: keyof typeof state, createControl: () => IControl | null) => {
            if (activeControls.current[name]) {
                mapCanvas.removeControl(activeControls.current[name]);
                delete activeControls.current[name];
            }
            if (state[name].enabled) {
                const control = createControl();
                if (control) {
                    mapCanvas.addControl(control, state[name].position);
                    activeControls.current[name] = control;
                }
            }
        };

        manageControl('terrain', () => mapCanvas.getSource('terrainSource') ? new TerrainControl(state.terrain.options) : null);
        manageControl('globe', () => new GlobeControl());
        manageControl('navigation', () => new NavigationControl(state.navigation.options));
        manageControl('fullscreen', () => new FullscreenControl(state.fullscreen.options));
        manageControl('scale', () => new ScaleControl(state.scale.options));
        manageControl('geolocate', () => new GeolocateControl(state.geolocate.options));
        
        manageControl('baseLayers', () => new BaseLayersPanelControl());
        manageControl('cameraPanel', () => new CameraPanelControl());
        manageControl('controlsPanel', () => new ControlsPanelControl());
        manageControl('interaction', () => new InteractionControl());
        
        return () => {
            mapCanvas.off('styledata', onStyleData);
        };
    });

    const handleNavOptionChange = (optionName: keyof NavigationControlOptions, value: boolean) => {
        const navState = controlsState.value.navigation;
        controlsState.value = { ...controlsState.value, navigation: { ...navState, options: { ...navState.options, [optionName]: value } } };
    };
    
    const isExpanded = useSignal(true);

    // Zwracamy null, jeśli panel ma być ukryty. Efekt powyżej i tak już się wykonał.
    if (!isMapControlsVisible.value) {
        return null;
    }

    // Ten JSX renderuje tylko panel po lewej stronie.
    return (
        <PanelOverCanvas 
            position={{ zIndex: 10, top: 10, left: 10, width: 280 }} 
            flexFlow={`column nowrap`}
            title="Kontrolki"
            toggle={isExpanded}
        >  
            {isExpanded.value && (
              <>
                    {/* Sekcja Nawigacji */}
                    <SectionOverCanvas flexFlow={`column wrap`}>
                      <div className="control-toggle-group main-toggle">
                            <label htmlFor="toggle-navigation">navigation</label>
                            <input id="toggle-navigation" type="checkbox" checked={controlsState.value.navigation.enabled} onChange={() => controlsState.value = {...controlsState.value, navigation: {...controlsState.value.navigation, enabled: !controlsState.value.navigation.enabled}}}/>
                        </div>
                        {controlsState.value.navigation.enabled && (
                            <div className="control-options">
                                <div className="control-toggle-group"><label htmlFor="option-showCompass">showCompass</label><input id="option-showCompass" type="checkbox" checked={controlsState.value.navigation.options.showCompass} onChange={(e) => handleNavOptionChange('showCompass', (e.target as HTMLInputElement).checked)} /></div>
                                <div className="control-toggle-group"><label htmlFor="option-showZoom">showZoom</label><input id="option-showZoom" type="checkbox" checked={controlsState.value.navigation.options.showZoom} onChange={(e) => handleNavOptionChange('showZoom', (e.target as HTMLInputElement).checked)} /></div>
                                <div className="control-toggle-group"><label htmlFor="option-visualizePitch">visualizePitch</label><input id="option-visualizePitch" type="checkbox" checked={controlsState.value.navigation.options.visualizePitch} onChange={(e) => handleNavOptionChange('visualizePitch', (e.target as HTMLInputElement).checked)} /></div>
                            </div>
                        )}
                    </SectionOverCanvas>

                    {/* Inne kontrolki */}
                    <SectionOverCanvas flexFlow={`column wrap`}>
                      <div className="control-toggle-group"><label htmlFor="toggle-terrain">terrain</label><input id="toggle-terrain" type="checkbox" checked={controlsState.value.terrain.enabled} onChange={() => controlsState.value = {...controlsState.value, terrain: {...controlsState.value.terrain, enabled: !controlsState.value.terrain.enabled}}}/></div>
                      <div className="control-toggle-group"><label htmlFor="toggle-globe">globe</label><input id="toggle-globe" type="checkbox" checked={controlsState.value.globe.enabled} onChange={() => controlsState.value = {...controlsState.value, globe: {...controlsState.value.globe, enabled: !controlsState.value.globe.enabled}}}/></div>
                      <div className="control-toggle-group"><label htmlFor="toggle-fullscreen">fullscreen</label><input id="toggle-fullscreen" type="checkbox" checked={controlsState.value.fullscreen.enabled} onChange={() => controlsState.value = {...controlsState.value, fullscreen: {...controlsState.value.fullscreen, enabled: !controlsState.value.fullscreen.enabled}}}/></div>
                      <div className="control-toggle-group"><label htmlFor="toggle-geolocate">geolocate</label><input id="toggle-geolocate" type="checkbox" checked={controlsState.value.geolocate.enabled} onChange={() => controlsState.value = {...controlsState.value, geolocate: {...controlsState.value.geolocate, enabled: !controlsState.value.geolocate.enabled}}}/></div>
                      <div className="control-toggle-group"><label htmlFor="toggle-scale">scale</label><input id="toggle-scale" type="checkbox" checked={controlsState.value.scale.enabled} onChange={() => controlsState.value = {...controlsState.value, scale: {...controlsState.value.scale, enabled: !controlsState.value.scale.enabled}}}/></div>
                    </SectionOverCanvas>
                    <SectionOverCanvas flexFlow={`column wrap`}>
                      {/* Przełączniki dla niestandardowych kontrolek UI */}
                      <div className="control-toggle-group"><label htmlFor="toggle-layers-btn">Przycisk Warstw</label><input id="toggle-layers-btn" type="checkbox" checked={controlsState.value.baseLayers.enabled} onChange={() => controlsState.value = {...controlsState.value, baseLayers: {...controlsState.value.baseLayers, enabled: !controlsState.value.baseLayers.enabled}}}/></div>
                      <div className="control-toggle-group"><label htmlFor="toggle-camera-btn">Przycisk Kamery</label><input id="toggle-camera-btn" type="checkbox" checked={controlsState.value.cameraPanel.enabled} onChange={() => controlsState.value = {...controlsState.value, cameraPanel: {...controlsState.value.cameraPanel, enabled: !controlsState.value.cameraPanel.enabled}}}/></div>
                      <div className="control-toggle-group"><label htmlFor="toggle-panel-btn">Przycisk Panelu</label><input id="toggle-panel-btn" type="checkbox" checked={controlsState.value.controlsPanel.enabled} onChange={() => controlsState.value = {...controlsState.value, controlsPanel: {...controlsState.value.controlsPanel, enabled: !controlsState.value.controlsPanel.enabled}}}/></div>
                      <div className="control-toggle-group"><label htmlFor="toggle-interaction-btn">Przycisk Interakcji</label><input id="toggle-interaction-btn" type="checkbox" checked={controlsState.value.interaction.enabled} onChange={() => controlsState.value = {...controlsState.value, interaction: {...controlsState.value.interaction, enabled: !controlsState.value.interaction.enabled}}}/></div>
                    </SectionOverCanvas>
              </>
            )}
        </PanelOverCanvas>
    );
}
