/** @jsxRuntime automatic */
/** @jsxImportSource $tsx-preact */

import { type VNode } from "$tsx-preact";
import { isBaseLayersPanelVisible } from "../store/MapState_signals.ts";
import { PanelOverCanvas, SectionOverCanvas, ButtonOverCanvas } from "./PanelOverCanvas.tsx";

/**
 * Pusty komponent-panel dla przyszłej funkcjonalności wyboru warstw bazowych.
 * Jego widoczność jest kontrolowana przez globalny sygnał.
 */
export function BaseLayers(): VNode | null {
    // Renderuj komponent tylko wtedy, gdy globalny sygnał na to pozwala
    if (!isBaseLayersPanelVisible.value) {
        return null;
    }

    return (
        <PanelOverCanvas 
            position={{ zIndex: 12, top: 50, right: 90, left: 50, height: '40%' }} 
            flexFlow={`column nowrap`}
            title="Warstwy Podkładowe"
            toggle={isBaseLayersPanelVisible}
        >
            <div className="panel-content">
                {/* Pusta zawartość panelu */}
                <p style={{textAlign: 'center', color: '#888'}}>Panel w budowie...</p>
            </div>
        </PanelOverCanvas>
    );
}
