/** @jsxRuntime automatic */
/** @jsxImportSource $tsx-preact */

import { type VNode, type ComponentChildren,  JSX } from "$tsx-preact";
import { type Signal } from "$tsx-preact-signal";

type CustomCSSProperties = JSX.CSSProperties & {
  [key: `--${string}`]: string | number;
};

interface PanelOverCanvasProps {
    position: CustomCSSProperties;
    title:string;
    toggle:Signal<boolean>;
    flexFlow: 'column nowrap' | 'row nowrap' | 'column wrap' | 'row wrap';
    children?: ComponentChildren;
    childrenHeader?: ComponentChildren;
}
/**
 * Pusty komponent-panel dla przyszłej funkcjonalności wyboru warstw bazowych.
 * Jego widoczność jest kontrolowana przez globalny sygnał.
 */
function PanelOverCanvas({ title, toggle, position, flexFlow, children, childrenHeader }: PanelOverCanvasProps): VNode {
    // Renderuj komponent tylko wtedy, gdy globalny sygnał na to pozwala
    //if (!isBaseLayersPanelVisible.value) {
    //    return null;
    //}

    return (
        <div className="panel-over-canvas" style={{...position, 'flexFlow': flexFlow}}  >
          <div className="panel-over-canvas-header">
            <div
                className="panel-over-canvas-header-toggle"
                onClick={() => toggle.value = !toggle.value}
            >
              <span>{title}</span>
              <svg
                  className={`panel-over-canvas-header-chevron-icon ${toggle.value ? 'expanded' : ''}`}
                  xmlns="http://www.w3.org/2000/svg"
                  width="18" height="18" viewBox="0 0 24 24" fill="none"
                  stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"
              >
                  <polyline points="6 9 12 15 18 9"></polyline>
              </svg>
            </div>
            
            { childrenHeader }
          </div>
          { children }
        </div>
    );
}


interface SectionOverCanvasProps {
    flexFlow: 'column nowrap' | 'row nowrap' | 'column wrap' | 'row wrap';
    children?: ComponentChildren;
}
/**
 * Pusty komponent-panel dla przyszłej funkcjonalności wyboru warstw bazowych.
 * Jego widoczność jest kontrolowana przez globalny sygnał.
 */
function SectionOverCanvas({ children, flexFlow }: SectionOverCanvasProps): VNode {

    return (
        <div className="section-over-canvas" style={{'flexFlow': flexFlow}} >
          { children }
        </div>
    );
}


interface ButtonOverCanvasProps {
  title:string;
    onClickHandle: JSX.MouseEventHandler<HTMLButtonElement>
    color?:'blue-button-over-canvas'|'darkblue-button-over-canvas';
}
/**
 * Pusty komponent-panel dla przyszłej funkcjonalności wyboru warstw bazowych.
 * Jego widoczność jest kontrolowana przez globalny sygnał.
 */
function ButtonOverCanvas({ onClickHandle,color,title}: ButtonOverCanvasProps): VNode {

    return (
      <button onClick={ onClickHandle } className={`button-over-canvas ${color??''}`}  type="button"> {title}</button>
    );
}

export {
  PanelOverCanvas, type PanelOverCanvasProps,
  SectionOverCanvas, type SectionOverCanvasProps,
  ButtonOverCanvas, type ButtonOverCanvasProps
};
