import type { 
  DragPanOptions, AroundCenterOptions, LngLatBoundsLike, GestureOptions,
  WebGLContextAttributesWithType
} from "$map-libre-gl$";


type AvailableRange = {
      moreTHAN?:number;
    noMoreTHAN?:number;
      lessTHAN?:number;
    noLessTHAN?:number;
      stepSIZE?:number;
};


/** Dozwolony zakres przybliżenia mapy */
const RANGE_ZOOM:AvailableRange = {
      noLessTHAN: 0.0, 
      noMoreTHAN: 22.0, 
      stepSIZE:0.01
};
/** Dozwolony zakres nachylenia mapy */
const RANGE_PITCH:AvailableRange = {
      noLessTHAN: 0, 
      noMoreTHAN:89, 
      stepSIZE:1
};
/** Dozwolony zakres rotacji mapy  */
const RANGE_BEARING:AvailableRange = {
      noLessTHAN: -179.9, 
      noMoreTHAN:180.0, 
      stepSIZE:0.1
};
/** Dozwolony zakres długości i szerokości geograficznej */
const RANGE_CENTER_LNG:AvailableRange = {
      moreTHAN:-180,
      noMoreTHAN:180
};
const RANGE_CENTER_LAT:AvailableRange = {
      moreTHAN:-86,
      noMoreTHAN:86
};

type MapOptions_GlobalConst = {      
      /* ! ADRES URL*/
      /**
       * Jeśli `true`, pozycja mapy (powiększenie, szerokość i długość geograficzna centrum, kierunek i nachylenie) będzie synchronizowana z fragmentem hash w adresie URL strony.
       * Na przykład, `http://path/to/my/page.html#2.59/39.26/53.07/-24.1/60`.
       * Opcjonalnie można podać dodatkowy ciąg znaków, aby wskazać hash w stylu parametru,
       * np. http://path/to/my/page.html#map=2.59/39.26/53.07/-24.1/60&foo=bar, gdzie foo
       * jest niestandardowym parametrem, a bar jest dowolnym hashem innym niż hash mapy.
       * @defaultValue false
       */
      hash?: boolean | string; 

      /* ! NAWIGACJA LIMITY */
      /**
       * Minimalny poziom powiększenia mapy (0-24).
       * @defaultValue 0
       */
      minZoom?: number | null; 
      /**
       * Maksymalny poziom powiększenia mapy (0-24).
       * @defaultValue 22
       */
      maxZoom?: number | null; 
      /**
       * Minimalny poziom nachylenia mapy (0-180).
       * @defaultValue 0
       */
      minPitch?: number | null;
      /**
       * Maksymalny poziom nachylenia mapy (0-180).
       * @defaultValue 60
       */
      maxPitch?: number | null;
      /**
       * Jeśli ustawione, mapa będzie ograniczona do podanych granic.
       */
      maxBounds?: LngLatBoundsLike;
         
      /**
       * Jeśli `true` lub ustawiono obiekt opcji, mapa jest dostępna na komputerach stacjonarnych tylko po przytrzymaniu klawisza Command/Ctrl i tylko na urządzeniach mobilnych za pomocą dwóch palców. Interakcja z mapą za pomocą zwykłych gestów spowoduje wyświetlenie ekranu informacyjnego. Gdy ta opcja jest włączona, "przeciągnij, aby pochylić" wymaga gestu trzema palcami. Gesty kooperacyjne są wyłączone, gdy mapa przechodzi w tryb pełnoekranowy za pomocą {@link FullscreenControl}.
       * @defaultValue false
       */
      cooperativeGestures?: GestureOptions;     
      /**
       * Próg, mierzony w stopniach, który określa, kiedy kierunek mapy zostanie automatycznie ustawiony na
       * północ. Na przykład, gdy `bearingSnap` wynosi 7, jeśli użytkownik obróci mapę w zakresie 7 stopni od 
       * północy, mapa automatycznie ustawi się dokładnie na północ.
       * @defaultValue 7
       */
      bearingSnap?: number;



      /* ! KONTROLA */
      /**
       * Jeśli `true`, włączona jest interakcja "przeciągnij, aby obrócić" (zobacz {@link DragRotateHandler}).
       * @defaultValue true
       */
      dragRotate?: boolean;
      /**
       * Jeśli `true`, włączona jest interakcja "przeciągnij, aby przesuwać". Wartość `Object` jest przekazywana jako opcje do {@link DragPanHandler.enable}.
       * @defaultValue true
       */
      dragPan?: boolean | DragPanOptions;
      /**
       * Jeśli `true`, włączone są skróty klawiaturowe (zobacz {@link KeyboardHandler}).
       * @defaultValue true
       */
      keyboard?: boolean;
      /**
       * Jeśli `true`, włączona jest interakcja "podwójne kliknięcie, aby powiększyć" (zobacz {@link DoubleClickZoomHandler}).
       * @defaultValue true
       */
      doubleClickZoom?: boolean;
      /**
       * Jeśli `true`, włączona jest interakcja "uszczypnij, aby obrócić i powiększyć". Wartość `Object` jest przekazywana jako opcje do {@link TwoFingersTouchZoomRotateHandler.enable}.
       * @defaultValue true
       */
      touchZoomRotate?: boolean | AroundCenterOptions;
      /**
       * Jeśli `true`, włączona jest interakcja "przeciągnij, aby pochylić". Wartość `Object` jest przekazywana jako opcje do {@link TwoFingersTouchPitchHandler.enable}.
       * @defaultValue true
       */
      touchPitch?: boolean | AroundCenterOptions;
      /**
       * Jeśli `true`, włączona jest interakcja "przewiń, aby powiększyć". Opcje {@link AroundCenterOptions} są przekazywane jako parametry do {@link ScrollZoomHandler.enable}.
       * @defaultValue true
       */
      scrollZoom?: boolean | AroundCenterOptions;
      /**
       * Jeśli `true`, włączona jest interakcja "powiększenie obszaru" (zobacz {@link BoxZoomHandler}).
       * @defaultValue true
       */
      boxZoom?: boolean;
      /**
       * Jeśli `true`, mapa będzie automatycznie zmieniać rozmiar po zmianie rozmiaru okna przeglądarki.
       * @defaultValue true
       */
      trackResize?: boolean;
      /**
       * Jeśli `false`, kontrola nachylenia mapy (pochylenia) za pomocą interakcji "przeciągnij, aby obrócić" zostanie wyłączona.
       * @defaultValue true
       */
      pitchWithRotate?: boolean;
      /**
       * Jeśli `false`, kontrola obrotu mapy (roll) za pomocą interakcji "przeciągnij, aby obrócić" zostanie wyłączona.
       * @defaultValue false
       */
      rollEnabled?: boolean;

      
      /* ! WYDAJNOŚĆ I WERSJA WEBGL */
      /**
       * Zestaw atrybutów `WebGLContextAttributes` stosowanych do kontekstu WebGL mapy.
       * Więcej szczegółów znajdziesz na stronie https://developer.mozilla.org/en-US/docs/Web/API/HTMLCanvasElement/getContext.
       * `contextType` można ustawić na `webgl2` lub `webgl`, aby wymusić wersję WebGL. Jeśli nie zostanie ustawiony, Maplibre spróbuje uzyskać odpowiedni kontekst.
       * @defaultValue antialias: false, powerPreference: 'high-performance', preserveDrawingBuffer: false, failIfMajorPerformanceCaveat: false, desynchronized: false, contextType: 'webgl2withfallback'
       */
      canvasContextAttributes?: WebGLContextAttributesWithType;

      
      /* ! ŹRÓDŁA I STYL MAPY */
      /**
       * Jeśli `true`, symbole z wielu źródeł mogą ze sobą kolidować podczas wykrywania kolizji. Jeśli `false`, wykrywanie kolizji jest przeprowadzane oddzielnie dla symboli w każdym źródle.
       * @defaultValue true
       */
      crossSourceCollisions?: boolean;
      /**
       * Jeśli `false`, walidacja stylu zostanie pominięta. Przydatne w środowisku produkcyjnym.
       * @defaultValue true
       */
      validateStyle?: boolean;


};
const mapOptions_globalConst:MapOptions_GlobalConst = {   
      /* ! ADRES URL */
      hash: true,
      /* ! NAWIGACJA */
      minZoom: RANGE_ZOOM.noLessTHAN,
      maxZoom: RANGE_ZOOM.noMoreTHAN,
      minPitch:RANGE_PITCH.noLessTHAN,
      maxPitch:RANGE_PITCH.noMoreTHAN,
      // // maxBounds
      /* ! KONTROLA */
      dragPan:true, // ?^ DragPanOptions;
      touchZoomRotate:true, // ?^ AroundCenterOptions;
      touchPitch:true, // ?^ AroundCenterOptions;
      scrollZoom:true, // ?^ AroundCenterOptions;
      boxZoom:true,
      dragRotate:true,
      keyboard: true,
      doubleClickZoom: true,
      pitchWithRotate:true,
      rollEnabled:true,
      trackResize:true,
      cooperativeGestures:false,
      bearingSnap:0,
      /* ! WYDAJNOŚĆ I WERSJA WEBGL */
      //  https://developer.mozilla.org/en-US/docs/Web/API/HTMLCanvasElement/getContext
      canvasContextAttributes: {
            antialias: true, 
            powerPreference: 'high-performance', 
            preserveDrawingBuffer: false, 
            failIfMajorPerformanceCaveat: false, 
            desynchronized: false, 
            contextType: 'webgl2'
      },
      /* ! ŹRÓDŁA I STYL MAPY */
      crossSourceCollisions:true,
      validateStyle:true,
};

export {
  type AvailableRange,RANGE_ZOOM,RANGE_PITCH,RANGE_BEARING,RANGE_CENTER_LNG,RANGE_CENTER_LAT,
  type MapOptions_GlobalConst, mapOptions_globalConst
};
