/** @jsxRuntime automatic */
/** @jsxImportSource $tsx-preact */

import { type ComponentChildren, type VNode, createContext } from "$tsx-preact";
import { useRef, useLayoutEffect, useEffect } from "$tsx-preact/hooks";
import { useSignal, useSignalEffect } from "$tsx-preact-signal";
import { Map as MapCore, type MapOptions, type StyleSpecification } from "$map-libre-gl$";
import { type MapOptions_OtherConfig } from "../store/MapOptions.ts";
import { mapOptions_globalConst } from "../store/MapOptions_const.ts";
import { 
    type MapOptions_InstanceVarInitStyle, 
    type MapOptions_InstanceVarInitCamera, 
} from "../store/MapOptions_store.ts";
import { isMapInteractive } from "../store/MapState_signals.ts"; 


/**
 * Tworzymy i eksportujemy Kontekst.
 * * Komponenty-dzieci (np. <Marker>, <Layer>) będą go używać,  
 * * aby uzyskać dostęp do instancji mapy.
 */
const MapContext = createContext<MapCore | null>(null);

/**
 * Definiuje propsy dla komponentu MapCanvas.
 */
interface MapCanvasProps {
    settingMapAtInitStyle: MapOptions_InstanceVarInitStyle;
    settingMapAtInitCamera: MapOptions_InstanceVarInitCamera;
    settingMapOthers?: MapOptions_OtherConfig;
    children?: ComponentChildren;
}

// --- KOMPONENT ---

/**
 * Komponent `MapCanvas`, respektujący priorytet stałych globalnych.
 * Inicjalizuje i zarządza instancją mapy MapLibre GL JS.
 * @param props - Właściwości konfiguracyjne i elementy potomne.
 */
function MapCanvas({ settingMapAtInitStyle, settingMapAtInitCamera, settingMapOthers, children }: MapCanvasProps): VNode {
    // Ref do kontenera mapy w DOM. MapLibre potrzebuje bezpośredniego dostępu do elementu HTML.
    const mapContainerRef = useRef<HTMLDivElement>(null);
    // Używamy sygnału do przechowywania instancji mapy. Zapewnia to reaktywność i dostęp w Kontekście.
    const mapCanvas = useSignal<MapCore | null>(null);

    // Używamy useLayoutEffect, aby zapewnić, że kontener DOM istnieje przed inicjalizacją mapy.
    // Jest to kluczowe dla bibliotek manipulujących bezpośrednio DOM-em.
    useLayoutEffect(() => {
        // Nie inicjalizuj ponownie, jeśli mapa już istnieje lub kontener nie jest gotowy.
        if (mapCanvas.value || !mapContainerRef.current) return;

        const combinedMapOptions: MapOptions = {
            container: mapContainerRef.current,
            // 1. NAJNIŻSZY PRIORYTET: Inne opcje.
            ...settingMapOthers,
            // 2. ŚREDNI PRIORYTET: Główne ustawienia startowe.
            ...settingMapAtInitStyle, ...settingMapAtInitCamera,
            // 3. NAJWYŻSZY, NIENARUSZALNY PRIORYTET: Stałe globalne.
            ...mapOptions_globalConst,
        };

        const mapInstance = new MapCore(combinedMapOptions);
        mapCanvas.value = mapInstance; // Ustawiamy instancję mapy w sygnale, co aktualizuje Kontekst.

        // Funkcja czyszcząca, która uruchamia się przy odmontowywaniu komponentu.
        return () => {
            mapInstance.remove();
            mapCanvas.value = null;
        };
        // Zależności efektu: mapa zostanie reinicjalizowana, jeśli zmienią się kluczowe obiekty konfiguracyjne.
    }, [settingMapAtInitStyle, settingMapAtInitCamera, settingMapOthers]);

    // ZARZĄDZANIE INTERAKTYWNOŚCIĄ MAPY ---
    useSignalEffect(() => {
        const mapInstance = mapCanvas.value;
        if (!mapInstance) return;

        const handlers = [
            mapInstance.dragPan, mapInstance.dragRotate, mapInstance.scrollZoom,
            mapInstance.keyboard, mapInstance.doubleClickZoom, mapInstance.touchZoomRotate,
            mapInstance.touchPitch
        ];

        if (isMapInteractive.value) {
            handlers.forEach((h) => h.enable());
        } else {
            handlers.forEach((h) => h.disable());
        }
    });

    // --- LOGIKA MODYFIKACJI STYLU ---
    useEffect(() => {
        const mapInstance = mapCanvas.value;
        if (!mapInstance) return;

        // Klucz API (można go przenieść do zmiennych środowiskowych)
        const KEYCODE_MAPTILER: string = `PHg2cj8QL4Svf3Wdjgsh`;

        // Funkcja, która zostanie wywołana po załadowaniu początkowego stylu
        const onStyleLoad = () => {
            // Pobieramy aktualny, w pełni załadowany styl
            const style = mapInstance.getStyle();

            // Modyfikujemy styl, dodając nowe źródła, teren, etc.
            const nextStyle: StyleSpecification = {
                ...style,
                sources: {
                    ...style.sources,
                    'terrainSource': {
                        type: 'raster-dem',
                        url: `https://api.maptiler.com/tiles/terrain-rgb-v2/tiles.json?key=${KEYCODE_MAPTILER}`,
                        tileSize: 256
                    },
                    'hillshadeSource': {
                        type: 'raster-dem',
                        url: `https://api.maptiler.com/tiles/terrain-rgb-v2/tiles.json?key=${KEYCODE_MAPTILER}`,
                        tileSize: 256
                    }
                },
                terrain: {
                    source: 'terrainSource',
                    exaggeration: 2.1
                },
                sky: {
                    'atmosphere-blend': [
                        'interpolate',
                        ['linear'],
                        ['zoom'],
                        0, 1,
                        2, 0
                    ],
                },
                layers: [
                    ...style.layers,
                    {
                        id: 'hills',
                        type: 'hillshade',
                        source: 'hillshadeSource',
                        layout: { visibility: 'visible' },
                        paint: { 'hillshade-shadow-color': '#473B24' }
                    },
                    // ---  BUDYNKI 3D ---
                    {
                        'id': 'building-3d',
                        'type': 'fill-extrusion',
                        'source': 'maptiler_planet', // To źródło jest już w stylach MapTiler
                        'source-layer': 'building',
                        'paint': {
                            // Kolor budynków
                            'fill-extrusion-color': [
                                'interpolate',
                                ['linear'],
                                ['get', 'render_height'],
                                0, 'lightgray',
                                200, 'royalblue',
                                400, 'darkviolet'
                            ],
                            // Wysokość budynków brana z danych
                            'fill-extrusion-height': ['get', 'render_height'],
                            // Podstawa budynków (od jakiej wysokości zaczyna się rysowanie)
                            'fill-extrusion-base': ['get', 'render_min_height'],
                            // Lekka przezroczystość dla lepszego efektu
                            'fill-extrusion-opacity': 0.85
                        }
                    }
                ]
            };
            
            // Ustawiamy nowy, zmodyfikowany styl na mapie
            mapInstance.setStyle(nextStyle);
        };

        // Nasłuchujemy na zdarzenie 'load'. To gwarantuje, że styl jest w pełni załadowany
        // zanim spróbujemy go modyfikować. Używamy 'once', aby funkcja wykonała się tylko raz.
        mapInstance.once('load', onStyleLoad);

    }, [mapCanvas.value]); // Ten efekt zależy tylko od dostępności instancji mapy.

    // Udostępniamy instancję mapy poprzez Kontekst.
    // Dzieci (`children`) renderujemy dopiero, gdy mapa jest gotowa (nie jest `null`),
    // aby miały pewny dostęp do instancji mapy z Kontekstu.
    return (
        // Ten div jest "płótnem" dla MapLibre
        <div className="map-canvas-container" ref={mapContainerRef}>
            {/* Dostawca Kontekstu udostępnia instancję mapy (z sygnału) wszystkim dzieciom.
                Renderujemy je dopiero wtedy, gdy mapa jest w pełni gotowa (map.value !== null),
                aby miały pewność, że mogą na niej operować.
            */}
            <MapContext.Provider value={mapCanvas.value}>
                {mapCanvas.value ? children : null}
            </MapContext.Provider>
        </div>
    );
}

export { MapCanvas, MapContext, type MapCanvasProps };
